static void opus_profunda(void *p)
{ struct ctx_profunda *c = p; c->r = exs_profunda(c->k, c->n); }
unsigned probatio_profunda_tutum(uint64_t k, uint64_t n, uint64_t *r)
{
  struct ctx_profunda c = { k, n, 0 };
  unsigned g = exs_tutela_curre(opus_profunda, &c);
  if (g == 0) *r = c.r;
  return g;
}
